import {meals,initialState,totals,nutritionTotals,createOrder,advanceOrder,cancelOrder,logMeal} from './model.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const icons={home:'⌂',favorites:'♡',cart:'🛒',orders:'▤',progress:'◷',community:'♧',profile:'☺',scanner:'▣'};
let user=sessionStorage.getItem('mealson-user'),page='home',filter='All meals',query='',orderFilter='Coming';
const key=()=>`mealson-demo-v1-${user}`;
function read(){try{const s=JSON.parse(localStorage.getItem(key()));if(s&&s.version===1&&s.profile&&Array.isArray(s.orders)&&Array.isArray(s.nutrition)&&Array.isArray(s.favorites)&&s.cart&&Array.isArray(s.audit)&&Array.isArray(s.notifications)&&Array.isArray(s.challenges))return s;}catch{}return initialState();}
let state=user?read():initialState();
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);
function save(){try{localStorage.setItem(key(),JSON.stringify(state));}catch{toast('Storage unavailable. Changes will last only in this session.');}}
function audit(action,outcome='allowed',resource=''){state.audit.unshift({timestamp:new Date().toISOString(),actor:user,action,outcome,resource});state.audit=state.audit.slice(0,100);save();}
function notify(text){state.notifications.unshift({id:crypto.randomUUID(),text,time:new Date().toISOString()});state.notifications=state.notifications.slice(0,30);save();}
let timer;function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.style.display='block';clearTimeout(timer);timer=setTimeout(()=>t.style.display='none',3300);}
const btn=(label,action,cls='btn',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const navItems=[['home','Discover'],['favorites','Favorites'],['orders','My orders'],['progress','Nutrition'],['community','Community'],['profile','Profile']];
function nav(){return navItems.map(([id,name])=>btn(`${icons[id]} <span>${name}</span>`,'nav',''+(page===id?'active':''),`data-page="${id}"`)).join('');}
function todayLogs(){return state.nutrition.filter(l=>l.date===new Date().toLocaleDateString('en-CA'));}
function welcome(){app.innerHTML=`<main class="welcome"><section class="welcome-card"><div class="brand"><span>✳</span>MealsOn</div><div class="welcome-art" aria-hidden="true">🥗</div><p class="eyebrow">Health delivered in a box</p><h1>Eat with intention.<br>Feel a little better.</h1><p>Good meals, simple nutrition tracking, and small habits that add up. Your healthy routine starts here.</p><div class="welcome-actions">${btn('Explore the demo →','enter','btn dark','data-user="alex"')}${btn('Try second profile','enter','btn secondary','data-user="sam"')}</div><p class="hint">Portfolio prototype · No real account or payment required.<br>Use fictional information. Demo data stays in this browser.</p></section></main>`;}
function render(){if(!user){welcome();return;}const count=totals(state.cart).count;app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span>✳</span>MealsOn</div><p class="tagline">HEALTH DELIVERED IN A BOX</p><nav class="nav" aria-label="Main">${nav()}</nav><div class="sidebar-note"><span class="badge">INTERACTIVE PROTOTYPE</span><p>Made for mindful meals.<br>Inspired by Divya's MealsOn designs.</p>${btn('About this demo','about','small')}</div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">A little healthier, every day</div><div class="greeting">Hey ${esc(state.profile.name)}, you hungry?</div></div><div class="top-actions"><span class="pill">📍 Demo delivery</span>${btn('♧','notifications','pill','aria-label="Notifications"')}${btn(`🛒 ${count}`,'nav','pill','data-page="cart" aria-label="Open cart"')}<label class="sr-only" for="switcher">Demo profile</label><select id="switcher" class="switcher"><option value="alex" ${user==='alex'?'selected':''}>Alex · demo profile</option><option value="sam" ${user==='sam'?'selected':''}>Sam · demo profile</option></select></div></header><div id="content">${content()}</div><footer class="footer">MealsOn portfolio prototype · Payments, delivery, wearable data & AI are simulated. <button data-action="about"><u>Details</u></button></footer></main><nav class="bottomnav" aria-label="Mobile">${[['home','Home'],['favorites','Saved'],['scanner','Scan'],['orders','Orders'],['profile','You']].map(([id,name])=>btn(`<span>${icons[id]}</span>${name}`,'nav',page===id?'active':'',`data-page="${id}"`)).join('')}</nav></div>`;}
function mealCard(m){return `<article class="meal"><div class="meal-art" style="background:${m.color}"><span aria-hidden="true">${m.emoji}</span>${btn(state.favorites.includes(m.id)?'♥':'♡','favorite','heart',`data-id="${m.id}" aria-label="${state.favorites.includes(m.id)?'Unsave':'Save'} ${m.name}" aria-pressed="${state.favorites.includes(m.id)}"`)}</div><div class="meal-body"><span class="metric-tag">${m.kcal} kcal · ${m.protein}g protein</span><h3>${btn(m.name,'detail','',`data-id="${m.id}"`)}</h3><p>${m.description}</p><div class="meal-footer"><span class="price">${money(Math.round(m.price*100))}</span>${btn('+','add','add',`data-id="${m.id}" aria-label="Add ${m.name} to cart"`)}</div></div></article>`;}
function title(h,p=''){return `<div class="title"><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>`;}
function empty(h,p,action='home'){return `<div class="empty"><div class="big">🥣</div><h2>${h}</h2><p class="sub">${p}</p>${btn('Explore meals','nav','btn','data-page="'+action+'"')}</div>`;}
function content(){switch(page){case'home':return home();case'favorites':return title('Your favorites','Good meals worth coming back to.')+(state.favorites.length?`<div class="grid">${meals.filter(m=>state.favorites.includes(m.id)).map(mealCard).join('')}</div>`:empty('Save something delicious','Tap a heart on a meal to keep it here.'));case'cart':return cart();case'orders':return orders();case'progress':return progress();case'community':return community();case'profile':return profile();case'scanner':return scanner();default:return home();}}
function home(){return `<section class="hero"><div><div class="eyebrow">Your next feel-good meal</div><h1>Find the best meal<br>for your day.</h1><p>Fresh flavors. Clear nutrition. Meals that fit the way you want to live.</p>${btn('Plan my meals →','plan','btn dark')}</div><div class="hero-art" aria-hidden="true">🥗</div></section><div class="search"><span aria-hidden="true">⌕</span><label for="search" class="sr-only">Search meals</label><input id="search" placeholder="What sounds good today?" value="${esc(query)}">${btn('▣','nav','','data-page="scanner" aria-label="Open meal scanner"')}</div><div class="chips">${['All meals','High protein','Plant based','Light meals'].map(f=>btn(f,'filter','chip '+(f===filter?'active':''),`data-filter="${f}" aria-pressed="${f===filter}"`)).join('')}</div><div class="section-heading"><h2>Fresh picks for you</h2><span class="hint">Sample menu</span></div><div id="meal-grid" class="grid">${filteredMeals()}</div><div class="section-heading"><h2>Your daily rhythm</h2>${btn('View nutrition →','nav','small','data-page="progress"')}</div><div class="columns"><div class="panel" style="background:var(--light)"><div class="eyebrow">Today's logged nutrition</div><h2 style="margin:12px 0">${nutritionTotals(todayLogs()).kcal} <span class="hint">/ ${state.profile.goal} kcal</span></h2><progress value="${nutritionTotals(todayLogs()).kcal}" max="${state.profile.goal}" aria-label="Daily calorie progress"></progress><p class="hint">Log meals you've eaten. Ordering a meal doesn't automatically log it.</p></div><div class="panel"><h3>Small habits, big momentum</h3><p class="sub">Join a challenge and make healthy eating a little more social.</p>${btn('Explore challenges →','nav','btn secondary','data-page="community"')}</div></div>`;}
function filteredMeals(){const ms=meals.filter(m=>(filter==='All meals'||m.category===filter)&&`${m.name} ${m.description}`.toLowerCase().includes(query.toLowerCase()));return ms.length?ms.map(mealCard).join(''):'<p class="sub">No meals match. Try another search or category.</p>';}
function cart(){const t=totals(state.cart);if(!t.count)return title('Your cart')+empty('A fresh start','Add a meal to start your order.');return title('Your cart','A good day starts with a good meal.')+`<div class="columns"><div class="panel">${Object.entries(state.cart).map(([id,q])=>{const m=meals.find(m=>m.id===id);return `<div class="row"><span class="row-emoji">${m.emoji}</span><div class="row-main"><h3>${m.name}</h3><span class="hint">${money(Math.round(m.price*100))} each</span></div><div class="qty">${btn('−','quantity','',`data-id="${id}" data-delta="-1" aria-label="Remove one ${m.name}"`)}<span>${q}</span>${btn('+','quantity','',`data-id="${id}" data-delta="1" aria-label="Add one ${m.name}"`)}</div></div>`;}).join('')}</div><form id="checkout" class="panel"><h3>Order summary</h3><div class="row"><span>Meals</span><strong>${money(t.subtotal)}</strong></div><div class="row"><span>Demo delivery fee</span><strong>$2.50</strong></div><div class="row"><strong>Total</strong><strong>${money(t.subtotal+250)}</strong></div><label for="address">Fictional delivery address</label><input id="address" name="address" required maxlength="160" placeholder="123 Demo Lane, Sample City"><div class="notice">Simulated checkout. No charge, card information, or actual delivery.</div><button class="btn dark" type="submit" style="width:100%">Place demo order →</button></form></div>`;}
const statuses=['Confirmed','Preparing','On the way','Delivered'];
function orders(){const os=state.orders.filter(o=>orderFilter==='History'?o.status===3:orderFilter==='Cancelled'?o.status===-1:o.status>=0&&o.status<3);return title('Your orders','From the first bite to the last mile.')+`<div class="chips">${['Coming','History','Cancelled'].map(f=>btn(f,'orderFilter','chip '+(orderFilter===f?'active':''),`data-filter="${f}"`)).join('')}</div>`+(os.length?os.map(o=>`<article class="panel order"><div class="section-heading" style="margin:0"><h3>${esc(o.id)}</h3><span class="status">${o.status<0?'Cancelled':statuses[o.status]}</span></div><p class="hint">${new Date(o.created).toLocaleString()} · ${money(o.total)}</p>${o.items.map(({id,q})=>`<div class="row"><span class="row-emoji">${meals.find(m=>m.id===id).emoji}</span><div class="row-main"><h3>${meals.find(m=>m.id===id).name}</h3><span class="hint">Quantity ${q}</span></div>${btn('Log as eaten','log','btn secondary small',`data-id="${id}" data-q="${q}"`)}</div>`).join('')}<div class="inline-actions">${o.status>=0?btn('Track order','track','btn small',`data-id="${o.id}"`):''}${o.status===0?btn('Cancel order','cancel','btn danger small',`data-id="${o.id}"`):''}</div></article>`).join(''):empty('No orders here yet','Your demo orders will appear in this tab.'));}
function progress(){const logs=todayLogs(),n=nutritionTotals(logs);const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {label:d.toLocaleDateString(undefined,{weekday:'short'}),total:nutritionTotals(state.nutrition.filter(l=>l.date===d.toLocaleDateString('en-CA'))).kcal};});return title('Your nutrition','A clear picture of your day, one meal at a time.')+`<div class="stats">${[['Calories',n.kcal,'kcal'],['Protein',n.protein,'g'],['Carbs',n.carbs,'g'],['Fat',n.fat,'g']].map(([name,value,unit])=>`<div class="stat"><span class="eyebrow">${name}</span><strong>${value}<small> ${unit}</small></strong></div>`).join('')}</div><div class="section-heading"><h2>Today's progress</h2>${btn('+ Log a meal','logDialog','btn small')}</div><div class="columns"><div class="panel"><div class="row"><h3>Daily calories</h3><span class="hint">${n.kcal} / ${state.profile.goal} kcal</span></div><progress max="${state.profile.goal}" value="${n.kcal}" aria-label="Calories logged today"></progress><div class="bar-chart">${days.map(d=>`<div class="bar-wrap"><div class="bar" style="height:${Math.min(120,d.total/state.profile.goal*120)}px" title="${d.total} kcal"></div>${d.label}</div>`).join('')}</div><p class="hint">Last 7 days · actual demo meal logs</p></div><div class="panel" style="background:#eaf3fc"><h3>💧 A moment to hydrate</h3><p class="sub">${state.water} of 8 glasses logged today</p><progress value="${state.water}" max="8" aria-label="Water glasses logged"></progress><div class="inline-actions">${btn('+ Add a glass','water','btn')}${btn('Reset today','resetWater','btn secondary')}</div><p class="hint">Demo habit goal, not a personalized hydration recommendation.</p></div></div><div class="section-heading"><h2>Meal journal</h2></div><div class="panel">${logs.length?logs.map(l=>`<div class="row"><div class="row-main"><h3>${meals.find(m=>m.id===l.mealId).name}</h3><span class="hint">${l.quantity} serving(s) · ${meals.find(m=>m.id===l.mealId).kcal*l.quantity} kcal</span></div>${btn('Remove','removeLog','small',`data-id="${l.id}"`)}</div>`).join(''):'<p class="sub">No meals logged today. Start with a meal from the sample menu.</p>'}</div>`;}
const challenges=[{id:'protein',icon:'💪',name:'Protein Boost',text:'Build a consistent meal-logging habit. Explore protein-rich dishes and check your daily progress.',color:'#f1f6d7'},{id:'water',icon:'💧',name:'Hydration Hustle',text:'Make space for water breaks. Log your glasses and keep your daily habit visible.',color:'#e8f1fb'},{id:'sugar',icon:'🍓',name:'No Sugar Week',text:'A mindful eating challenge. Check in daily and reflect on your food choices.',color:'#fbe8e4'}];
function community(){return title('Better, together','Find a little motivation in a shared routine.')+`<div class="grid">${challenges.map(c=>`<article class="challenge" style="background:${c.color}"><div class="challenge-icon">${c.icon}</div><span class="eyebrow">7-day community challenge</span><h2 style="margin:10px 0">${c.name}</h2><p>${c.text}</p>${btn(state.challenges.includes(c.id)?'Joined ✓':'Join challenge','challenge','btn dark',`data-id="${c.id}" aria-pressed="${state.challenges.includes(c.id)}"`)}${state.challenges.includes(c.id)?`<div class="inline-actions">${btn(state.checkins?.[c.id]===new Date().toLocaleDateString('en-CA')?'Checked in today ✓':'Check in today','checkin','btn secondary small',`data-id="${c.id}"`)}</div>`:''}</article>`).join('')}</div><div class="notice">Local challenge demo. No real community members or leaderboards; joining doesn't share your health data.</div>`;}
function profile(){return title('Your profile','Your preferences. Your pace.')+`<div class="columns"><form id="profileForm" class="panel"><h3>☺ ${esc(state.profile.name)}</h3><label for="name">Demo display name</label><input id="name" name="name" value="${esc(state.profile.name)}" required maxlength="40"><label for="goal">Daily calorie goal (demo)</label><input id="goal" name="goal" type="number" min="500" max="6000" step="1" value="${state.profile.goal}" required><label for="diet">Meal preference</label><select id="diet" name="diet">${['All meals','High protein','Plant based','Light meals'].map(d=>`<option ${state.profile.diet===d?'selected':''}>${d}</option>`).join('')}</select><div class="inline-actions"><button class="btn dark" type="submit">Save preferences</button></div><p class="hint">These goals are test values, not dietary advice.</p></form><div class="panel"><h3>Privacy & integrations</h3><p class="sub">Try consent controls with a simulated wearable connection.</p><label class="checks"><input id="consent" type="checkbox" ${state.profile.consent?'checked':''}> Allow mock wearable syncing</label>${btn('Sync sample activity','sync','btn secondary')}<p id="syncResult" class="hint">${state.lastSync?esc(state.lastSync):'No wearable data has been synced.'}</p><div class="notice">Demo profiles separate browser storage only. This is not authentication or server-enforced authorization.</div><div class="inline-actions">${btn('Export demo data','export','btn secondary small')}${btn('Security event log','audit','btn secondary small')}${btn('Reset this profile','reset','btn danger small')}${btn('Exit demo','logout','btn secondary small')}</div></div></div>`;}
function scanner(){return title('AI meal scanner','Explore the scan-to-journal experience.')+`<div class="columns"><div class="panel"><div class="scan-art" id="scanPreview">🥗</div><label for="scanFile">Optional meal photo (stays on your device)</label><input type="file" id="scanFile" accept="image/*"><p class="hint">The photo is previewed locally. It is not uploaded, identified, or analyzed.</p></div><div class="panel"><span class="badge">SIMULATED AI RESULT</span><h2 style="margin:15px 0">Try a sample scan</h2><p class="sub">Select the sample meal to preview its nutrition. These results come from the menu, not from your photo.</p><label for="scanMeal">Sample meal</label><select id="scanMeal">${meals.map(m=>`<option value="${m.id}">${m.name}</option>`).join('')}</select><div class="inline-actions">${btn('Show sample result','scan','btn dark')}</div><div id="scanResult"></div></div></div>`;}
function modal(html){dialog.innerHTML=btn('×','close','close','aria-label="Close dialog"')+html;if(!dialog.open)dialog.showModal();}
function switchUser(id){user=id;sessionStorage.setItem('mealson-user',id);state=read();if(!localStorage.getItem(key()))state.profile.name=id==='alex'?'Alex':'Sam';const today=new Date().toLocaleDateString('en-CA');if(state.waterDate!==today){state.water=0;state.waterDate=today;}save();query='';page='home';render();}
function dispatch(action,el){const id=el.dataset.id;switch(action){case'enter':switchUser(el.dataset.user);break;case'nav':page=el.dataset.page;render();break;case'close':dialog.close();break;case'filter':filter=el.dataset.filter;render();break;case'orderFilter':orderFilter=el.dataset.filter;render();break;case'add':state.cart[id]=(state.cart[id]||0)+1;save();toast('Added to your cart');render();break;case'quantity':state.cart[id]=Math.max(0,(state.cart[id]||0)+Number(el.dataset.delta));if(!state.cart[id])delete state.cart[id];save();render();break;case'favorite':state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();break;case'detail':{const m=meals.find(m=>m.id===id);modal(`<div class="scan-art" style="background:${m.color}">${m.emoji}</div><h2 style="margin-top:20px">${m.name}</h2><p class="sub">${m.description}</p><p>${m.kcal} kcal · ${m.protein}g protein · ${m.carbs}g carbs · ${m.fat}g fat</p><div class="inline-actions">${btn('Add to cart · '+money(Math.round(m.price*100)),'add','btn',`data-id="${id}"`)}${btn('Log as eaten','log','btn secondary',`data-id="${id}"`)}</div><p class="hint">Sample nutrition estimates. Ingredient/allergen verification is not implemented.</p>`);break;}case'plan':filter=state.profile.diet;render();document.querySelector('#search').focus();toast('Showing meals for your saved preference');break;case'log':state=logMeal(state,id,Number(el.dataset.q)||1);save();toast('Meal logged in your journal');if(dialog.open)dialog.close();render();break;case'logDialog':modal(`<h2>Log a meal</h2><p class="sub">Choose a meal you've eaten.</p>${meals.map(m=>`<div class="row"><span>${m.emoji} ${m.name}</span>${btn('Log','log','btn small',`data-id="${m.id}"`)}</div>`).join('')}`);break;case'removeLog':state.nutrition=state.nutrition.filter(l=>l.id!==id);save();render();break;case'water':{const today=new Date().toLocaleDateString('en-CA');if(state.waterDate!==today){state.water=0;state.waterDate=today;}state.water=Math.min(8,state.water+1);save();render();break;}case'resetWater':state.water=0;save();render();break;case'challenge':state.challenges=state.challenges.includes(id)?state.challenges.filter(c=>c!==id):[...state.challenges,id];save();render();break;case'checkin':state.checkins={...state.checkins,[id]:new Date().toLocaleDateString('en-CA')};save();render();toast('Today’s check-in saved');break;case'track':track(id);break;case'advance':state=advanceOrder(state,id);audit('delivery_status_advanced','allowed',id);render();track(id);break;case'cancel':modal(`<h2>Cancel this demo order?</h2><p class="sub">No payment was taken. The order will move to Cancelled.</p>${btn('Confirm cancellation','confirmCancel','btn danger',`data-id="${id}"`)}`);break;case'confirmCancel':state=cancelOrder(state,id);audit('order_cancelled','allowed',id);dialog.close();render();toast('Demo order cancelled');break;case'notifications':modal(`<h2>Notifications</h2>${state.notifications.length?state.notifications.map(n=>`<div class="row"><div><p>${esc(n.text)}</p><span class="hint">${new Date(n.time).toLocaleString()}</span></div></div>`).join(''):'<p class="sub">You’re all caught up. Place an order to see an update.</p>'}`);break;case'sync':if(!state.profile.consent){audit('wearable_sync','denied');toast('Sync blocked: grant consent first.');}else{state.lastSync='Sample activity: 4,200 steps. No provider connected.';audit('wearable_sync');document.querySelector('#syncResult').textContent=state.lastSync;toast('Sample activity synced');}break;case'audit':modal(`<h2>Security event log</h2><p class="hint">Local demo events; editable browser storage is not a tamper-resistant audit trail.</p>${state.audit.length?state.audit.slice(0,15).map(a=>`<div class="row"><div><strong>${esc(a.action)}</strong><p class="hint">${esc(a.outcome)} · ${esc(a.actor)}<br>${esc(a.timestamp)}</p></div></div>`).join(''):'<p class="sub">No events yet. Try wearable sync or place an order.</p>'}`);break;case'export':{const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='mealson-demo-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Exported this demo profile');break;}case'reset':modal(`<h2>Reset this demo profile?</h2><p class="sub">This clears local orders, favorites, logs and preferences for ${esc(state.profile.name)}.</p>${btn('Reset demo data','confirmReset','btn danger')}`);break;case'confirmReset':state=initialState();state.profile.name=user==='alex'?'Alex':'Sam';save();dialog.close();render();break;case'logout':sessionStorage.removeItem('mealson-user');user=null;dialog.close();render();break;case'about':modal(`<h2>About MealsOn</h2><p class="sub">A working front-end prototype inspired by Divya's MealsOn mobile screens and the Group 7 MIS 6308 system design.</p><p class="sub">Meals, orders, payments, delivery, AI and wearables use sample data. Browser-local profiles are for demonstration and provide no security boundary.</p><p class="sub">No real account, payment processor or nutrition provider is connected. This is a separate implementation; the Lovable project has not been modified.</p>`);break;case'scan':{const m=meals.find(m=>m.id===document.querySelector('#scanMeal').value);document.querySelector('#scanResult').innerHTML=`<div class="notice">Sample result: ${m.name}</div><p><strong>${m.kcal} kcal</strong> · ${m.protein}g protein · ${m.carbs}g carbs · ${m.fat}g fat</p>${btn('Log sample meal','log','btn',`data-id="${m.id}"`)}`;break;}}}
function track(id){const o=state.orders.find(o=>o.id===id);if(!o)return;modal(`<h2>Track your order</h2><p class="hint">${esc(o.id)} · Simulated delivery</p><div class="scan-art">${o.status===3?'📦':'🚲'}</div><div class="steps">${statuses.map((s,i)=>`<div class="step ${i<=o.status?'done':''}">${i<=o.status?'✓ ':''}${s}</div>`).join('')}</div><p class="sub">${esc(o.address)}</p>${o.status<3?btn('Advance demo delivery →','advance','btn',`data-id="${id}"`):'<p class="sub">Delivered! Log your meal when you eat it.</p>'}`);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)dispatch(el.dataset.action,el);});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;document.querySelector('#meal-grid').innerHTML=filteredMeals();}});
document.addEventListener('change',e=>{if(e.target.id==='switcher')switchUser(e.target.value);if(e.target.id==='consent'){state.profile.consent=e.target.checked;audit(e.target.checked?'consent_granted':'consent_revoked');toast(e.target.checked?'Mock consent granted':'Mock consent revoked');}if(e.target.id==='scanFile'){const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>10*1024*1024){toast('Choose an image smaller than 10 MB.');e.target.value='';return;}const u=URL.createObjectURL(file),img=document.createElement('img');img.alt='Your locally selected meal photo';img.style.cssText='max-width:100%;max-height:300px;border-radius:16px;object-fit:contain';img.src=u;img.onload=()=>URL.revokeObjectURL(u);const preview=document.querySelector('#scanPreview');preview.textContent='';preview.append(img);}});
document.addEventListener('submit',e=>{if(e.target.id==='checkout'){e.preventDefault();try{state=createOrder(state,new FormData(e.target).get('address'));audit('order_created','allowed',state.orders[0].id);notify('Your demo order is confirmed.');page='orders';orderFilter='Coming';render();toast('Order confirmed — no payment taken');}catch(err){toast(err.message);}}if(e.target.id==='profileForm'){e.preventDefault();const d=new FormData(e.target),name=String(d.get('name')).trim(),goal=Number(d.get('goal'));if(!name||!Number.isInteger(goal)||goal<500||goal>6000){toast('Check your name and demo goal.');return;}state.profile={...state.profile,name,goal,diet:d.get('diet')};save();render();toast('Preferences saved');}});
if(user)switchUser(user);else render();
